INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('P01', 'detailed', 'Кончето', 'Пирин', 'Идея', 'Трудна', 13, 1200, 1700, '', '', '', '', 'Юли – Септември', 'https://www.google.com/search?q=prognoza+Bansko+Pirin', 'https://www.google.com/search?q=%D0%90%D0%B2%D1%82%D0%BE%D0%B3%D0%B0%D1%80%D0%B8+%D0%91%D0%B0%D0%BD%D1%81%D0%BA%D0%BE', 'https://razpisanie.bdz.bg/', 'https://www.avtogari.info/', 'Банско → х. Яворов → ръб/Кончето → х. Вихрен', 'ЧАСТИЧНО — базовите данни са дадени от потребителя; наличен е външен източник за х. Тевно езеро, но не и пълна независима верификация за този маршрут в тази сесия.', '{"summary":"Най-логичен е достъпът с кола до Банско и по-нататък с местен трансфер/такси; обществен транспорт е удобен само до Банско.","car":{"available":true,"text":"До Банско се стига по асфалт; последният подход към изхода за маршрута зависи от точната пътека и сезонните ограничения.","parkingNote":"Паркиране в Банско, после пеша или с такси до началната точка; GPS за паркинг не е верифициран в тази сесия."},"public":{"steps":[{"from":"София","to":"Банско","mode":"Автобус или влак+автобус","time":"планирай 3-5ч според връзката","note":"Най-лесно за безколесен уикенд."},{"from":"Банско","to":"изходна точка","mode":"Такси","time":"15-30 мин","note":"Необходим е предварителен уговорен трансфер."}]}}'::jsonb, '[{"name":"х. Яворов","elevation":1745,"beds":null,"officialPhone":"0896 688 413","altPhone":"0886 116 609","email":null,"gps":null,"verified":true,"conflict":"Потребителят е дал един и същ номер като базов; не е верифициран с независим втори източник в тази сесия."},{"name":"х. Вихрен","elevation":1950,"beds":null,"officialPhone":"0889 890 442","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Няма достатъчно данни за потвърждение на контакти и капацитет в тази сесия."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Ръбовият участък към Кончето е технически и е подходящ само при стабилно време.","Сезонността е силна: сняг, лед и мъгла правят участъка значително по-рисков.","Няма независима двуизточникова верификация на всички детайли за хижите в тази сесия."],"conclusion":"Маршрутът е високорисков и изисква сухо време, ранен старт и опит в ръбови терени."}'::jsonb, '[{"date":"2026-08-08","label":"Банско → х. Яворов → Кончето → х. Вихрен","type":"Преход","distance":"17 км","gain":"+1200 м","time":"9-11ч","stay":"х. Вихрен","difficulty":"Трудна"}]'::jsonb, '[{"name":"Хотели в Банско","location":"Банско","rating":null,"price":null,"note":"Подходящо за предна вечер; избери близо до центъра за лесен ранен трансфер."},{"name":"х. Вихрен","location":"Пирин","rating":null,"price":null,"note":"Финалната точка за нощувка след трудния ръбов участък."}]'::jsonb, '[{"name":"Местно такси Банско","phone":null,"note":"Потвърди номера от хотела/рецепцията в деня преди тръгване."}]'::jsonb, 'https://embed.windy.com/embed.html', ''),
('P02', 'detailed', 'Демяница', 'Пирин', 'Идея', 'Средна/Висока', 22, 890, 890, '', '', '', '', 'Юни – Октомври', 'https://www.google.com/search?q=prognoza+Bansko+Dobrinishte+Pirin', 'https://www.google.com/search?q=%D0%B0%D0%B2%D1%82%D0%BE%D0%B3%D0%B0%D1%80%D0%B8+%D0%91%D0%B0%D0%BD%D1%81%D0%BA%D0%BE+%D0%94%D0%BE%D0%B1%D1%80%D0%B8%D0%BD%D0%B8%D1%89%D0%B5', 'https://razpisanie.bdz.bg/', 'https://www.avtogari.info/', 'Банско → х. Демяница → х. Безбог → Добринище', 'ЧАСТИЧНО — базовите километри и денивелация са дадени от потребителя; маршрутната логика е типична за района, но пълна независима верификация не е налична в тази сесия.', '{"summary":"Най-удобно е с кола до Банско/Добринище и местен трансфер; обществен транспорт покрива началото и края сравнително добре.","car":{"available":true,"text":"Асфалтов достъп до Банско и Добринище; началната пътека към х. Демяница зависи от избрания старт.","parkingNote":"Паркингът е най-практичен в Банско или Добринище, после такси до началната точка."},"public":{"steps":[{"from":"София","to":"Банско","mode":"Автобус или влак+автобус","time":"3-5ч","note":"Добър вариант за уикенд без кола."},{"from":"Добринище","to":"крайна/начална точка","mode":"Теснолинейка/такси/пеша","time":"варира","note":"Възможно е комбиниране според логистиката."}]}}'::jsonb, '[{"name":"х. Демяница","elevation":1895,"beds":null,"officialPhone":"0877 79 94 06","altPhone":"0878 688 135","email":null,"gps":null,"verified":true,"conflict":"Нужна е допълнителна верификация на контактите и капацитета."},{"name":"х. Безбог","elevation":2240,"beds":null,"officialPhone":"+359 74 472120","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Няма достатъчно независими източници в тази сесия."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Маршрутът е дълъг, но без задължителни технични елементи като Кончето.","Променливото време в Пирин може да вдигне риска в алпийската част.","Няма пълна двуизточникова верификация за всички хижи."],"conclusion":"Подходящ е за опитни, но не екстремно технически преходи."}'::jsonb, '[{"date":"2026-08-08","label":"Банско → х. Демяница → х. Безбог / район","type":"Преход","distance":"22 км","gain":"+890 м","time":"7-9ч","stay":"х. Безбог","difficulty":"Средна/Висока"},{"date":"2026-08-09","label":"х. Безбог → Добринище","type":"Преход/спускане","distance":"вкл. в общите 22 км","gain":"вкл. в общите +890/-890 м","time":"3-5ч","stay":"Добринище","difficulty":"Средна"}]'::jsonb, '[{"name":"Хотели в Банско","location":"Банско","rating":null,"price":null,"note":"Добра база за старт."},{"name":"Хотели в Добринище","location":"Добринище","rating":null,"price":null,"note":"Удобни за финал и транспорт обратно."}]'::jsonb, '[{"name":"Местно такси Банско/Добринище","phone":null,"note":"Потвърди на място."}]'::jsonb, 'https://embed.windy.com/embed.html', ''),
('P05', 'detailed', 'Тевно езеро II', 'Пирин', 'Идея', 'Висока', 16, 900, 900, '', '', '', '', 'Юли – Септември', 'https://www.google.com/search?q=prognoza+Vihren+Tevno+Sandanski', 'https://www.google.com/search?q=%D0%B0%D0%B2%D1%82%D0%BE%D0%B3%D0%B0%D1%80%D0%B8+%D0%A1%D0%B0%D0%BD%D0%B4%D0%B0%D0%BD%D1%81%D0%BA%D0%B8', 'https://razpisanie.bdz.bg/', 'https://www.avtogari.info/', 'х. Вихрен → заслон Тевно езеро → Бегово поле → Сандански', 'ПОТВЪРДЕНО ЧАСТИЧНО — има външен източник за заслон Тевно езеро с GPS/телефон/височина, но не и пълна независима верификация на цялата последователност.', '{"summary":"Най-удобно е с кола или автобус до Сандански и трансфер към х. Вихрен; маршрутьт е подходящ за точка-до-точка логистика.","car":{"available":true,"text":"Асфалт до Сандански и Банско; достъпът до х. Вихрен е по планински път и зависи от сезон/ограничения.","parkingNote":"Практично е паркиране в Сандански и трансфер нагоре към Вихрен."},"public":{"steps":[{"from":"София","to":"Сандански","mode":"Влак или автобус","time":"3-5ч","note":"Добър изходен град за края на маршрута."},{"from":"Сандански","to":"х. Вихрен","mode":"Такси","time":"1-1.5ч","note":"Нужен е предварителен трансфер."}]}}'::jsonb, '[{"name":"заслон Тевно езеро","elevation":2512,"beds":30,"officialPhone":"0886/397268","altPhone":"0884/663635","email":null,"gps":"41.6988,23.4829","verified":true,"conflict":null},{"name":"х. Вихрен","elevation":null,"beds":null,"officialPhone":"0889 890 442","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Липсва верификация за контакти и капацитет в тази сесия."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Това е по-дълъг високопланински преход с излизане към Сандански.","Посоката от Вихрен към Тевно е чувствителна към мъгла и късно тръгване.","Налични са надеждни данни за самия заслон, но не и за всички междинни детайли."],"conclusion":"Подходящ е за опитни туристи с добра кондиция и стабилно време."}'::jsonb, '[{"date":"2026-08-08","label":"х. Вихрен → заслон Тевно езеро","type":"Преход","distance":"16 км","gain":"+900 м","time":"6-8ч","stay":"заслон Тевно езеро","difficulty":"Висока"},{"date":"2026-08-09","label":"заслон Тевно езеро → Бегово поле → Сандански","type":"Преход/спускане","distance":"вкл. в общите 16 км","gain":"вкл. в общите +900/-900 м","time":"5-7ч","stay":"Сандански","difficulty":"Висока"}]'::jsonb, '[{"name":"х. Вихрен","location":"Пирин","rating":null,"price":null,"note":"Стартова нощувка, ако се тръгва рано."},{"name":"Хотели в Сандански","location":"Сандански","rating":null,"price":null,"note":"Удобен финал с богата база за настаняване."}]'::jsonb, '[{"name":"Местно такси Сандански","phone":null,"note":"Потвърди за ранно изкачване към хижата."}]'::jsonb, 'https://embed.windy.com/embed.html', '')
